package com.adib.maintenance;
import android.app.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.lang.reflect.*;import java.io.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w360dp-h800dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class ModernChatVisualTest {
 void set(MainActivity a,String n,Object v)throws Exception{Field f=MainActivity.class.getDeclaredField(n);f.setAccessible(true);f.set(a,v);}Object get(MainActivity a,String n)throws Exception{Field f=MainActivity.class.getDeclaredField(n);f.setAccessible(true);return f.get(a);}void call(MainActivity a,String n)throws Exception{Method m=MainActivity.class.getDeclaredMethod(n);m.setAccessible(true);m.invoke(a);}
 void capture(boolean dark,float scale,int width,String name)throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();set(a,"dark",dark);set(a,"chatRequestRunning",true);android.content.res.Configuration cfg=a.getResources().getConfiguration();cfg.fontScale=scale;a.getResources().updateConfiguration(cfg,a.getResources().getDisplayMetrics());a.getResources().getDisplayMetrics().scaledDensity=scale;JSONArray comments=new JSONArray().put(new JSONObject().put("id","1").put("authorName","Коллега").put("text","Проверь привод конвейера и датчик.").put("createdAt","2026-10-02T12:00:00Z")).put(new JSONObject().put("id","2").put("authorName","Коллега").put("text","Фото узла").put("createdAt","2026-10-02T12:01:00Z").put("attachments",new JSONArray().put(new JSONObject().put("url","https://files.notion.so/photo.png")))).put(new JSONObject().put("id","3").put("authorName","ilqar mamedov").put("text","Хорошо, проверю сегодня").put("createdAt","2026-10-02T12:05:00Z"));JSONArray threads=new JSONArray().put(new JSONObject().put("taskId","A").put("title","Проверить привод").put("comments",comments));a.getPreferences(0).edit().putString("chat_threads_cache",threads.toString()).apply();call(a,"showChat");set(a,"activeChatTaskId","A");set(a,"chatConversationOpen",true);call(a,"showChatPage");Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();View conversation=(View)get(a,"chatConversationPage");View root=(View)((View)conversation.getParent()).getParent();root.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(760,View.MeasureSpec.EXACTLY));root.layout(0,0,width,760);assertTrue(((View)get(a,"chatComposer")).getHeight()>0);assertTrue(((View)get(a,"chatComposer")).getRight()<=width);Bitmap bmp=Bitmap.createBitmap(width,760,Bitmap.Config.ARGB_8888);root.draw(new Canvas(bmp));File dir=new File("/data/adib-fullscreen/previews");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){bmp.compress(Bitmap.CompressFormat.PNG,100,out);}Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}
 @Test public void light360()throws Exception{capture(false,1f,360,"modern-chat-android");}
 @Test public void dark320LargeText()throws Exception{capture(true,1.4f,320,"modern-chat-android-dark-large");}
}
